268	/** The sheet's pools with their members, total share and whether they are balanced, and each member's cut
269	 *  of the pool's pot: the sheet's pot for a pool that is a member of none, else its cut in the pool above. A
270	 *  person with a hold in force on the sheet's today (the as-of date when one is given) gets no cut. A member
271	 *  whose dates do not include that day is left out entirely: not in the total share, not in the balance, no cut. */
272	public class RespondWithPools {
273	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
274	
275	    public void respond(@PathVariable("sheetId") String sheetId,
276	            @RequestParam(name = "asOf", required = false) String asOf, PoolStore store, SettingStore settings,
277	            PersonStore people, SheetStore sheets, ObjectResponse<List<PoolResponse>> response) {
278	        String sheet = sheetId.trim();
279	        LocalDate on = History.date(asOf);
280	        BigDecimal sheetPot = (on == null ? settings : settings.asOf(on)).pot(sheet);
281	        Map<Long, List<PoolStore.Member>> members = store.members(sheet, on);
282	        List<PoolStore.Pool> pools = store.list(sheet, on);
283	        LocalDate today = on == null ? sheets.today(sheet) : on;
284	        Set<Long> held = (on == null ? people.list(sheet) : people.listAsOf(sheet, on)).stream()
285	                .filter(p -> p.getHolds().stream().anyMatch(h -> h.covers(today))).map(Person::getId)
286	                .collect(Collectors.toSet());
287	        // each member pool to the pool it is a member of, and its share there
288	        Map<Long, Long> parents = new HashMap<>();
289	        members.forEach((poolId, ms) -> ms.stream().filter(m -> m.memberPoolId() != null)
290	                .forEach(m -> parents.put(m.memberPoolId(), poolId)));
291	        Map<Long, List<BigDecimal>> cuts = new HashMap<>();
292	        for (PoolStore.Pool p : pools) {
293	            cutsOf(p.id(), members, parents, held, today, sheetPot, cuts, 0);
294	        }
295	        response.send(pools.stream().map(p -> {
296	            List<PoolStore.Member> ms = members.getOrDefault(p.id(), List.of());
297	            List<BigDecimal> cs = cuts.get(p.id());
298	            List<PoolResponse.MemberResponse> shown = new ArrayList<>();
299	            for (int i = 0; i < ms.size(); i++) {
300	                PoolStore.Member m = ms.get(i);
301	                shown.add(new PoolResponse.MemberResponse(m.personId(), m.memberPoolId(), m.name(),
302	                        m.share().setScale(2).toPlainString(), m.retired(),
303	                        cs == null || cs.get(i) == null ? null : cs.get(i).toPlainString(),
304	                        m.from() == null ? null : m.from().toString(), m.to() == null ? null : m.to().toString()));
305	            }
306	            BigDecimal total = total(ms, today);
307	            return new PoolResponse(p.id(), p.name(), shown, total.toPlainString(), total.compareTo(HUNDRED) == 0);
308	        }).toList());
309	    }
310	
311	    /** The total of the members' shares, a retired member's counting as given, one whose dates do not include
312	     *  today as 0.00. */
313	    private static BigDecimal total(List<PoolStore.Member> ms, LocalDate today) {
314	        return ms.stream().filter(m -> m.covers(today)).map(PoolStore.Member::share)
315	                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
316	    }
317	
318	    /** The pool's members' cuts of its pot, null when it is not balanced or has no pot: the sheet's pot for a
319	     *  pool that is a member of none, else its cut in the pool above. Kept in {@code cuts} as worked out. */
320	    private static List<BigDecimal> cutsOf(long poolId, Map<Long, List<PoolStore.Member>> members,
321	            Map<Long, Long> parents, Set<Long> held, LocalDate today, BigDecimal sheetPot,
322	            Map<Long, List<BigDecimal>> cuts, int depth) {
323	        if (cuts.containsKey(poolId) || depth > members.size() + 1) {
324	            return cuts.get(poolId);
325	        }
326	        BigDecimal pot = sheetPot;
327	        Long parent = parents.get(poolId);
328	        if (parent != null) {
329	            List<BigDecimal> above = cutsOf(parent, members, parents, held, today, sheetPot, cuts, depth + 1);
330	            pot = null;
331	            List<PoolStore.Member> siblings = members.getOrDefault(parent, List.of());
332	            for (int i = 0; above != null && i < siblings.size(); i++) {
333	                if (Long.valueOf(poolId).equals(siblings.get(i).memberPoolId())) {
334	                    pot = above.get(i);
335	                }
336	            }
337	        }
338	        List<PoolStore.Member> ms = members.getOrDefault(poolId, List.of());
339	        List<BigDecimal> found = total(ms, today).compareTo(HUNDRED) == 0 && pot != null ? cuts(ms, held, today, pot) : null;
340	        cuts.put(poolId, found);
341	        return found;
342	    }
343	
344	    /** Each member's cut, in the members' order: the pot times their share over the shares of the members with a
345	     *  cut, rounded half to even to two decimals (a retired or held member's is 0.00, their share spread over the
346	     *  others, and each is 0.00 when none has a cut); null for every member when each whose dates include today is
347	     *  retired. The remainder goes to the member with the smallest non-zero cut, the latest added on a tie
348	     *  (a member with no cut gets none; when no cut is non-zero, to the last member with a cut and a share), so
349	     *  the cuts total exactly the pot. A member whose dates do not include today has no cut (null). */
350	    private static List<BigDecimal> cuts(List<PoolStore.Member> ms, Set<Long> held, LocalDate today,
351	            BigDecimal pot) {
352	        List<PoolStore.Member> current = ms.stream().filter(m -> m.covers(today)).toList();
353	        if (!current.isEmpty() && current.stream().allMatch(PoolStore.Member::retired)) {
354	            List<BigDecimal> none = new ArrayList<>();
355	            ms.forEach(m -> none.add(null));
356	            return none;
357	        }
358	        BigDecimal shares = ms.stream().filter(m -> m.covers(today) && hasCut(m, held)).map(PoolStore.Member::share)
359	                .reduce(BigDecimal.ZERO, BigDecimal::add);
360	        List<BigDecimal> cuts = new ArrayList<>();
361	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
362	        int smallest = -1;
363	        int last = -1;
364	        for (int i = 0; i < ms.size(); i++) {
365	            PoolStore.Member m = ms.get(i);
366	            if (!m.covers(today)) {
367	                cuts.add(null);
368	                continue;
369	            }
370	            boolean cut = hasCut(m, held) && shares.signum() > 0;
371	            BigDecimal c = cut ? pot.multiply(m.share()).divide(shares, 2, RoundingMode.HALF_EVEN)
372	                    : BigDecimal.ZERO.setScale(2);
373	            cuts.add(c);
374	            sum = sum.add(c);
375	            if (cut && m.share().signum() > 0) {
376	                last = i;
377	            }
378	            if (cut && c.signum() > 0 && (smallest < 0 || c.compareTo(cuts.get(smallest)) <= 0)) {
379	                smallest = i;
380	            }
381	        }
382	        int to = smallest >= 0 ? smallest : last;
383	        if (to >= 0) {
384	            cuts.set(to, cuts.get(to).add(pot.subtract(sum)).setScale(2));
385	        }
386	        return cuts;
387	    }
388	
389	    /** Whether the member gets a cut: not retired, and not a person with a hold in force. */
390	    private static boolean hasCut(PoolStore.Member m, Set<Long> held) {
391	        return !m.retired() && (m.personId() == null || !held.contains(m.personId()));
392	    }
393	}
