437	/** Refuses a member by a viewer, of a pool or person not on the sheet, of a person already in the pool, or
438	 *  with a share that is not a number of at most two decimals, more than 0.00 and at most 100.00. A member pool
439	 *  is refused when it is already a member of a pool, when it would contain the pool through any chain (or is
440	 *  the pool itself), or when the chain of pools would be more than three deep. A from- or to-date is optional;
441	 *  one that is not a date, or a to-date before the from-date, is refused. */
442	public class ValidateMember {
443	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
444	    private static final int MAX_DEPTH = 3;
445	
446	    public void validate(@PathVariable("sheetId") String sheetId, @PathVariable("poolId") String poolId,
447	            @RequestBody MemberRequest request, Out<MemberInput> body, RoleStore roles, PoolStore pools,
448	            PersonStore people) throws InvalidSheetException {
449	        String sheet = sheetId.trim();
450	        String user = request == null || request.user() == null ? "" : request.user().trim();
451	        roles.refuseChange(sheet, user);
452	        PoolStore.Pool pool;
453	        try {
454	            pool = pools.find(sheet, Long.parseLong(poolId.trim()));
455	        } catch (NumberFormatException e) {
456	            pool = null;
457	        }
458	        if (pool == null) {
459	            throw new InvalidSheetException("No such pool");
460	        }
461	        PoolStore.Pool member = request == null || request.memberPoolId() == null ? null
462	                : pools.find(sheet, request.memberPoolId());
463	        if (request != null && request.memberPoolId() != null && member == null) {
464	            throw new InvalidSheetException("No such pool to add");
465	        }
466	        Person person = member != null || request == null || request.personId() == null ? null
467	                : people.find(sheet, request.personId());
468	        if (member == null && person == null) {
469	            throw new InvalidSheetException("A person is required");
470	        }
471	        String text = request.share() == null ? "" : request.share().trim();
472	        if (!text.matches("\\d+(\\.\\d{1,2})?")) {
473	            throw new InvalidSheetException("A share is a percent with at most two decimals");
474	        }
475	        BigDecimal share = new BigDecimal(text).setScale(2);
476	        if (share.signum() <= 0 || share.compareTo(HUNDRED) > 0) {
477	            throw new InvalidSheetException("A share is more than 0.00 and at most 100.00");
478	        }
479	        LocalDate from = date(request.from());
480	        LocalDate to = date(request.to());
481	        if (from != null && to != null && to.isBefore(from)) {
482	            throw new InvalidSheetException("The to date must not be before the from date");
483	        }
484	        if (member != null) {
485	            refuseNesting(sheet, pool, member, pools);
486	            body.set(new MemberInput(pool, null, member.id(), member.name(), share, from, to, user));
487	            return;
488	        }
489	        if (pools.isMember(pool.id(), person.getId())) {
490	            throw new InvalidSheetException(person.getName() + " is already in " + pool.name());
491	        }
492	        body.set(new MemberInput(pool, person.getId(), null, person.getName(), share, from, to, user));
493	    }
494	
495	    /** The date given, or null when blank. */
496	    private static LocalDate date(String value) throws InvalidSheetException {
497	        String text = value == null ? "" : value.trim();
498	        if (text.isEmpty()) {
499	            return null;
500	        }
501	        try {
502	            return LocalDate.parse(text);
503	        } catch (DateTimeParseException e) {
504	            throw new InvalidSheetException("Not a date: " + text);
505	        }
506	    }
507	
508	    private static void refuseNesting(String sheet, PoolStore.Pool pool, PoolStore.Pool member, PoolStore pools)
509	            throws InvalidSheetException {
510	        if (member.id() == pool.id()) {
511	            throw new InvalidSheetException(pool.name() + " cannot be a member of itself");
512	        }
513	        Map<Long, Long> parents = pools.parents(sheet);
514	        if (parents.containsKey(member.id())) {
515	            throw new InvalidSheetException(member.name() + " is already a member of a pool");
516	        }
517	        // the pools above the pool, counting it
518	        int above = 0;
519	        for (Long at = pool.id(); at != null; at = parents.get(at)) {
520	            if (at == member.id()) {
521	                throw new InvalidSheetException(member.name() + " already contains " + pool.name());
522	            }
523	            above++;
524	        }
525	        if (above + depth(member.id(), parents) > MAX_DEPTH) {
526	            throw new InvalidSheetException("A chain of pools is at most " + MAX_DEPTH + " deep");
527	        }
528	    }
529	
530	    /** How deep the chain of pools from {@code poolId} down goes, counting it. */
531	    private static int depth(long poolId, Map<Long, Long> parents) {
532	        int deepest = 0;
533	        for (Map.Entry<Long, Long> e : parents.entrySet()) {
534	            if (e.getValue() == poolId) {
535	                deepest = Math.max(deepest, depth(e.getKey(), parents));
536	            }
537	        }
538	        return deepest + 1;
539	    }
