      postJson(`/api/sheets/${encodeURIComponent(sheet)}/pools/${pool.id}/members`, { ...m, user }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheet) });
      setPersonId('');
      setShare('');
      setFrom('');
      setTo('');
    },
  });
  const submit = useSubmitOnce(add);

  return (
